#!/usr/bin/env node

/**
 * ULS User Custom Component Generator
 * 
 * Generates a new custom component in src/uls-components/src/custom-components/
 * This is for end users to create their own custom components.
 * 
 * Usage:
 *   uls -g component ComponentName
 *   node scripts/create-component.js ComponentName
 * 
 * Note: For ULS internal components, use: npm run create-uls-component
 */

const fs = require('fs');
const path = require('path');

// ==========================================================================
// TEMPLATES
// ==========================================================================

const COMPONENT_TEMPLATE = `import React from 'react';
import clsx from 'clsx';

/**
 * {{ComponentName}} Component
 * 
 * @param {Object} props - Component props
 * @param {React.ReactNode} props.children - Content to display
 * @param {string} props.className - Additional CSS classes
 * @param {string} props.variant - Visual variant (primary, secondary, success, danger, etc.)
 * @param {string} props.size - Size variant (small, medium, large)
 */
export const {{ComponentName}} = ({
  children,
  className,
  variant = 'primary',
  size = 'medium',
  ...props
}) => {
  return (
    <div
      className={clsx(
        'uls-{{kebabName}}',
        {
          [variant]: variant,
          [size]: size,
        },
        className
      )}
      {...props}
    >
      {children}
    </div>
  );
};

export default {{ComponentName}};
`;

const INDEX_TEMPLATE = `// ==========================================================================
// {{ComponentName}} Component Export
// ==========================================================================

export { {{ComponentName}} } from './{{kebabName}}';
export { default } from './{{kebabName}}';
export { BasicExample } from './{{kebabName}}.example';
`;

const EXAMPLE_TEMPLATE = `import React from 'react';
import { {{ComponentName}} } from './{{kebabName}}';

// ==========================================================================
// Basic Example
// ==========================================================================

export function BasicExample() {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <{{ComponentName}} variant="primary" size="medium">
        Primary {{ComponentName}}
      </{{ComponentName}}>
      
      <{{ComponentName}} variant="secondary" size="small">
        Secondary Small {{ComponentName}}
      </{{ComponentName}}>
      
      <{{ComponentName}} variant="success" size="large">
        Success Large {{ComponentName}}
      </{{ComponentName}}>
    </div>
  );
}
`;

// ==========================================================================
// UTILITY FUNCTIONS
// ==========================================================================

function generateComponentVariations(name) {
  // Convert ComponentName to various formats
  const pascalCase = name.charAt(0).toUpperCase() + name.slice(1).replace(/-([a-z])/g, (g) => g[1].toUpperCase());
  const kebabCase = name.replace(/([A-Z])/g, '-$1').toLowerCase().replace(/^-/, '');
  const camelCase = pascalCase.charAt(0).toLowerCase() + pascalCase.slice(1);
  
  return {
    ComponentName: pascalCase,
    componentName: camelCase,
    kebabName: kebabCase,
    KEBAB_NAME: kebabCase.toUpperCase()
  };
}

function replaceTemplateVariables(template, variables) {
  let result = template;
  Object.entries(variables).forEach(([key, value]) => {
    const regex = new RegExp(`{{${key}}}`, 'g');
    result = result.replace(regex, value || '');
  });
  return result;
}

function findProjectRoot() {
  let currentDir = process.cwd();
  
  // Look for src/uls-components directory
  while (currentDir !== path.dirname(currentDir)) {
    const ulsComponentsPath = path.join(currentDir, 'src', 'uls-components');
    if (fs.existsSync(ulsComponentsPath)) {
      return currentDir;
    }
    currentDir = path.dirname(currentDir);
  }
  
  // Fallback to current directory
  return process.cwd();
}

function updateIndexFile(projectRoot, componentName, variations) {
  const indexPath = path.join(projectRoot, 'src', 'uls-components', 'src', 'index.js');
  
  // Ensure directory exists
  const indexDir = path.dirname(indexPath);
  if (!fs.existsSync(indexDir)) {
    fs.mkdirSync(indexDir, { recursive: true });
  }
  
  let indexContent = '';
  if (fs.existsSync(indexPath)) {
    indexContent = fs.readFileSync(indexPath, 'utf8');
  } else {
    indexContent = `// ==========================================================================
// ULS Components Library
// ==========================================================================
// React component library built on top of ULS design system
// Export all components for easy importing
// ==========================================================================

`;
  }
  
  // Check if export already exists
  const exportPattern = new RegExp(`export.*${variations.ComponentName}.*from`, 'i');
  if (exportPattern.test(indexContent)) {
    console.log(`⚠️  Warning: ${variations.ComponentName} already exported in index.js`);
    return false;
  }
  
  // Add export
  const exportLine = `export { ${variations.ComponentName} } from './custom-components/${variations.kebabName}';\n`;
  
  // Add before the closing comment or at the end
  if (indexContent.trim().endsWith('// ==========================================================================')) {
    indexContent = indexContent.trim() + '\n\n' + exportLine;
  } else {
    indexContent += exportLine;
  }
  
  fs.writeFileSync(indexPath, indexContent, 'utf8');
  return true;
}

// ==========================================================================
// MAIN GENERATOR FUNCTION
// ==========================================================================

function generateComponent(componentName) {
  const projectRoot = findProjectRoot();
  const variations = generateComponentVariations(componentName);
  
  // Paths
  const customComponentsPath = path.join(projectRoot, 'src', 'uls-components', 'src', 'custom-components');
  const componentPath = path.join(customComponentsPath, variations.kebabName);
  const componentFile = path.join(componentPath, `${variations.kebabName}.jsx`);
  const indexFile = path.join(componentPath, 'index.js');
  const exampleFile = path.join(componentPath, `${variations.kebabName}.example.jsx`);
  
  // Check if component already exists
  if (fs.existsSync(componentPath)) {
    console.error(`❌ Error: Component ${variations.ComponentName} already exists at:`);
    console.error(`   ${componentPath}`);
    process.exit(1);
  }
  
  // Create directory
  if (!fs.existsSync(customComponentsPath)) {
    fs.mkdirSync(customComponentsPath, { recursive: true });
  }
  fs.mkdirSync(componentPath, { recursive: true });
  console.log(`📁 Created directory: ${path.relative(process.cwd(), componentPath)}`);
  
  // Generate component file
  const componentContent = replaceTemplateVariables(COMPONENT_TEMPLATE, variations);
  fs.writeFileSync(componentFile, componentContent, 'utf8');
  console.log(`📝 Created: ${path.relative(process.cwd(), componentFile)}`);
  
  // Generate index file
  const indexContent = replaceTemplateVariables(INDEX_TEMPLATE, variations);
  fs.writeFileSync(indexFile, indexContent, 'utf8');
  console.log(`📝 Created: ${path.relative(process.cwd(), indexFile)}`);
  
  // Generate example file
  const exampleContent = replaceTemplateVariables(EXAMPLE_TEMPLATE, variations);
  fs.writeFileSync(exampleFile, exampleContent, 'utf8');
  console.log(`📝 Created: ${path.relative(process.cwd(), exampleFile)}`);
  
  // Update main index.js
  const indexUpdated = updateIndexFile(projectRoot, componentName, variations);
  if (indexUpdated) {
    console.log(`✅ Updated: ${path.relative(process.cwd(), path.join(projectRoot, 'src', 'uls-components', 'src', 'index.js'))}`);
  }
  
  console.log(`\n🎉 Successfully generated ${variations.ComponentName} component!`);
  console.log(`\n📦 Component location:`);
  console.log(`   ${componentPath}`);
  console.log(`\n💡 Next steps:`);
  console.log(`   1. Customize the component in: ${componentFile}`);
  console.log(`   2. Add examples in: ${exampleFile}`);
  console.log(`   3. Import and use: import { ${variations.ComponentName} } from '@uls/components'`);
}

// ==========================================================================
// CLI INTERFACE
// ==========================================================================

const componentName = process.argv[2];

if (!componentName) {
  console.error('❌ Error: Component name is required');
  console.log('\nUsage:');
  console.log('  uls -g component <ComponentName>');
  console.log('  node scripts/create-component.js <ComponentName>');
  console.log('\nExamples:');
  console.log('  uls -g component MyButton');
  console.log('  uls -g component UserCard');
  console.log('  uls -g component DataTable');
  process.exit(1);
}

try {
  generateComponent(componentName);
} catch (error) {
  console.error('\n❌ Error:', error.message);
  if (error.stack) {
    console.error('\nStack trace:', error.stack);
  }
  process.exit(1);
}

